  R <- matrix(0, nrow = max_level, ncol = max_level)
  h <- b - a
  R[1, 1] <- 0.5 * h * (f(a) + f(b))
  if (max_level > 1) {
    for (k in 2:max_level) {
      h <- h / 2
      n_new <- 2^(k - 2)
      mid_pts <- a + (2 * seq_len(n_new) - 1) * h
      R[k, 1] <- 0.5 * R[k - 1, 1] + h * sum(vapply(mid_pts, f, numeric(1)))
      for (j in 2:k) {
        factor <- 4^(j - 1)
        R[k, j] <- (factor * R[k, j - 1] - R[k - 1, j - 1]) / (factor - 1)
      }
    }
  }
  R[max_level, max_level]
}

